for(let i=0;i<NF;i++){pact.time=i/NF*pdur;pmix.update(0);boy.updateMatrixWorld(true);ft.l.getWorldPosition(fa);ft.r.getWorldPosition(fb);gaps.push(Math.abs(fa.z-fb.z))}
for(let h=0;h<2;h++){let bi=h*NF/2;for(let i=h*NF/2;i<(h+1)*NF/2;i++)if(gaps[i]<gaps[bi])bi=i;REST[h]=bi/NF*pdur}
