 mk(new T.BoxGeometry(ax1-ax0+1.1,.55,.7),pm,AX,5.35,az,1);
 const sg=cv(1024,256),sx=sg.getContext('2d');sx.fillStyle='#0d3b8e';sx.fillRect(0,0,1024,256);sx.fillStyle='#0a2c6b';sx.fillRect(0,0,1024,14);sx.fillRect(0,242,1024,14);
 sx.fillStyle='#fff';sx.beginPath();sx.roundRect?sx.roundRect(36,36,184,184,34):sx.rect(36,36,184,184);sx.fill();
