 sx.fillStyle='#fff';sx.textAlign='left';sx.font='bold 74px sans-serif';sx.fillText('STUDENT PARKING',258,100);sx.fillStyle='#ffd54a';sx.font='600 50px sans-serif';sx.fillText('ANITS  \u2022  Park slowly',266,180);
