/* ---------- CSE / ECE / EEE / Chemical blocks: 3D models, entrances face each other across the central road ---------- */
{
 const brez=(await parse(B_BREZ)).scene;
 const bbox=o=>{o.updateMatrixWorld(true);return new T.Box3().setFromObject(o)};
 const bB=bbox(brez);
 const palImg=await new Promise(r=>{const i=new Image();i.onload=()=>r(i);i.src=PAL});
 const palC={};const palTex=col=>palC[col]||(palC[col]=palMk(col));const palMk=col=>{const c=cv(256,256),x=c.getContext('2d');x.drawImage(palImg,0,0);x.fillStyle=col;x.fillRect(32,64,32,32);   // recolour the wall swatch
  const t=new T.CanvasTexture(c);t.flipY=false;t.anisotropy=4;return t};
 const lp=(await parse(B_LP)).scene,bL=bbox(lp);
 // low-poly block: door is on its +X side. rot turns the door: 0 = east, PI = west, -PI/2 = south, PI/2 = north
 function lpAt(s,ys,x,z,rot,wall){
  const inner=new T.Group(),m=lp.clone(true);
  m.traverse(o=>{if(!o.isMesh)return;o.castShadow=o.receiveShadow=true;o.material=o.material.clone();const q=o.material;
   q.metalness=0;q.roughness=.85;q.map=palTex(wall);q.color.setRGB(1,1,1);q.emissiveMap=q.map;q.emissive.setRGB(.22,.22,.22);q.needsUpdate=true});
  const c=bL.getCenter(new T.Vector3());m.position.set(-c.x,-bL.min.y,-c.z);inner.add(m);inner.scale.set(s,ys,s);
  const out=new T.Group();out.position.set(x,0,z);out.rotation.y=rot;out.add(inner);sc.add(out)}
 // fill a plot with a row of buildings, all entrances on the `face` side (E/W/N/S)
 function lpRow(plot,face,h,wall,name,accent){
  const ys=h/(bL.max.y-bL.min.y),s=ys*1.4,dep=(bL.max.x-bL.min.x)*s,w=(bL.max.z-bL.min.z)*s;
  const x0=wx(plot[0]),x1=wx(plot[2]),z0=wz(plot[1]),z1=wz(plot[3]),ax=face==='N'||face==='S',L=ax?x1-x0:z1-z0;
  const n=Math.max(1,Math.floor((L-1)/w)),gap=(L-n*w)/(n+1),rot={E:0,W:Math.PI,S:-Math.PI/2,N:Math.PI/2}[face];
  for(let i=0;i<n;i++){const c=(ax?x0:z0)+gap*(i+1)+w*(i+.5);let x,z;
   if(face==='E'){x=x1-.6-dep/2;z=c}else if(face==='W'){x=x0+.6+dep/2;z=c}else if(face==='S'){z=z1-.6-dep/2;x=c}else{z=z0+.6+dep/2;x=c}
   lpAt(s,ys,x,z,rot,wall);(window.__lp=window.__lp||[]).push({plot,face,x,z,w,dep,h});ax?addCol(x,z,w,dep,h):addCol(x,z,dep,w,h);
   campus.detailBlock({x,z,rotation:rot,depth:dep,length:w,height:h,name,sign:i===Math.floor(n/2),accent})}}
 // model +X side = entrance side; Z = along the building
 function make(proto,bb,[sx,sy,sz],face,plot,h,tint,wall){
  const inner=new T.Group(),m=proto.clone(true);
  m.traverse(o=>{if(!o.isMesh)return;o.castShadow=o.receiveShadow=true;
   o.material=o.material.clone();const q=o.material;q.metalness=0;q.roughness=.9;q.normalMap=null;q.metalnessMap=null;q.roughnessMap=null;
   if(wall){q.map=palTex(wall);q.color.setRGB(1,1,1)}else{q.color.set(tint);q.emissiveMap=q.map;q.emissive.setRGB(.28,.28,.28)}q.needsUpdate=true});
  const c=bb.getCenter(new T.Vector3());m.position.set(-c.x,-bb.min.y,-c.z);inner.add(m);inner.scale.set(sx,sy,sz);
  const dep=(bb.max.x-bb.min.x)*sx,len=(bb.max.z-bb.min.z)*sz,hh=(bb.max.y-bb.min.y)*sy;
  const out=new T.Group(),cz=wz((plot[1]+plot[3])/2);let x;
  if(face==='E'){x=wx(plot[2])-.6-dep/2;out.rotation.y=0}else{x=wx(plot[0])+.6+dep/2;out.rotation.y=Math.PI}   // E: door faces east, W-side blocks face the road
  out.position.set(x,0,cz);out.add(inner);sc.add(out);
  addCol(x,cz,dep,len,hh);
  return{out,dep,len,hh}}
 const door=(o,dep,hh)=>{ // entrance door, steps and canopy on the +X face (only needed for the panel-house model)
  const f=dep/2,add=(g,m,x,y,z)=>{const q=mk(g,m,0,0,0,1);q.position.set(x,y,z);o.add(q)};
  add(new T.BoxGeometry(.2,3.4,3),lam(0x3b2616),f+.05,1.7,0);
  add(new T.BoxGeometry(.5,3.4,.25),lam(0x2a2a30),f+.1,1.7,-1.6);add(new T.BoxGeometry(.5,3.4,.25),lam(0x2a2a30),f+.1,1.7,1.6);
  add(new T.BoxGeometry(2.4,.28,5),lam(0x55585f),f+1.1,3.6,0);
  add(new T.BoxGeometry(1.8,.3,4),lam(0xb0aca0),f+.9,.15,0)};
 const zFor=plot=>Math.min(24.2,(plot[3]-plot[1])*S-.8)/(bB.max.z-bB.min.z);   // length fits each plot
 const put=(face,plot,tint,name,accent)=>{const z=zFor(plot),r=make(brez,bB,[z*1.3,z,z],face,plot,11.5,tint);door(r.out,r.dep,r.hh);
  campus.detailBlock({x:r.out.position.x,z:r.out.position.z,rotation:r.out.rotation.y,depth:r.dep,length:r.len,height:r.hh,name,sign:true,accent})};
 // west of the road: entrance faces EAST (+x).  east of the road: entrance faces WEST.
 put('E',[102,246,156,281],0xd8ded9,'CSE Block',0x8a6a55);   // CSE
 put('W',[170,244,230,279],0xd9d4cb,'ECE Block',0x9a7263);   // ECE
 put('E',[109,205,155,239],0xd3dccb,'Chemical Block',0x698478);   // Chemical
 put('W',[172,201,232,231],0xdcd0c7,'EEE Block',0x9b7968);   // EEE
 // Mechanical / IT / Civil / CSM: low-poly blocks (doors face the open roads and courtyards)
 lpRow([101,116,226,156],'S',10,'#d4c5b0','Mechanical Block',0xa77463); // faces the campus
 lpRow([260,143,282,237],'W',11,'#d4c6b4','IT Block',0x857f70);         // faces the main road
 lpRow([276,61,358,117],'W',14,'#bcae9c','Civil Block',0x9e7060);      // north wing
 lpRow([288,137,356,224],'W',14,'#bcae9c','Civil Block',0x9e7060);     // south wing
 lpRow([286,226,319,246],'S',7,'#cac2ac','CSM Block',0x7b8a83);       // faces the basketball ground
 campus.flushBuildings();

}

