 [-.15,.15].forEach(x=>{const e=new T.Mesh(new T.SphereGeometry(.055,8,6),lam(0x111111));e.position.set(x,h-.34,r*.92);g.add(e)});
 if(beret){const hat=new T.Mesh(new T.SphereGeometry(r*.95,12,6,0,6.3,0,1.2),lam(beret));hat.position.y=h-r+.1;g.add(hat)}
