/* ---------- Remy: Mixamo character with Walking animation ---------- */
{const gl=await parse(B_REMY),rm=gl.scene,hold=new T.Group(),clip=gl.animations[0];
 hold.userData.arms=[new T.Group(),new T.Group()]; // capsule NPCs animate arms; Remy uses his skeleton instead
 rm.traverse(o=>{if(o.isMesh){o.castShadow=true;o.frustumCulled=false}});
 rm.updateMatrixWorld(true);const bb=new T.Box3().setFromObject(rm),k=1.75/(bb.max.y-bb.min.y);
 rm.scale.setScalar(k);rm.position.y=-bb.min.y*k;hold.add(rm);          // 1.75 m tall, feet on the ground
 const mix=new T.AnimationMixer(rm),act=mix.clipAction(clip);act.play();
 const dur=clip.duration,TS=.9,REST=[1/24,13/24];let t=0,sp=1;           // TS .9 = feet match his 1.5 u/s walking speed
 // REST = the two "legs passing" frames: when he stops to talk he finishes the current step and holds there
 const tick=(dt,mv)=>{
  if(mv){sp+=(1-sp)*Math.min(1,dt*6);t=(t+dt*TS*sp)%dur}
  else{const r=Math.min(...REST.map(q=>((q-t)%dur+dur)%dur));if(r>.004){sp=Math.max(.25,Math.min(1,r*5));t=(t+Math.min(dt*TS*sp,r))%dur}}
  act.time=t;mix.update(0)};
 const R=[[118,426],[118,360],[140,343],[160,343],[160,286],[160,215],[160,286],[160,343],[246,343]].map(q=>W2(...q));
 const n=addNPC({id:'stu',name:'Remy (Student)',p:[118,426],route:R,ri:1,dir:1,face:Math.PI,mdl:hold,rm:tick,h:1.75,
  L:{d:["Hey! I'm Remy, second year. First day at ANITS?","Tip: the canteen near the Civil Block has the best chai.","Sorry, I have to run. I'm late for class!"]}});
 n.x=R[0][0];n.z=R[0][1]}

