const FPH=.35,RD_TOP=.08,FP_TOP=RD_TOP+FPH,FP_LIFT=FP_TOP-.04,RAMP_L=FPH/Math.tan(12*Math.PI/180),RAMP_W=3.6;
const GATE_PATHS=campus.gateSidepaths();
const FP={x0:wx(59.2),x1:wx(82)+1.2,z0:wz(346),z1:wz(420.5)};
const ENTR=[wz(357.5),wz(385),wz(408.5)];
const RAMPS=[...ENTR.map(zc=>({ax:'x',dir:1,x0:FP.x1,x1:FP.x1+RAMP_L,z0:zc-RAMP_W/2,z1:zc+RAMP_W/2})),
 {ax:'z',dir:-1,x0:FP.x0,x1:FP.x1,z0:FP.z0-RAMP_L,z1:FP.z0},{ax:'z',dir:1,x0:FP.x0,x1:FP.x1,z0:FP.z1,z1:FP.z1+RAMP_L}];
const roadAt=(x,z)=>ROADS.some(r=>x>=wx(r[0])&&x<=wx(r[2])&&z>=wz(r[1])&&z<=wz(r[3]))?RD_TOP:0;
/* ---------- raised footpath around the sand field (replaces the green border): map-px rects, bevelled kerb ---------- */
// Only the short apron at the sand field remains. The parallel north/south spur
// duplicated the entrance sidewalk and continued almost into the main gate.
const SANDFP=[[0,0,0,0]],SF_B=.3,SF_C=.1,SF_BASE=.04,SF_TOP=.2;
const SF_R=SANDFP.map(r=>[wx(r[0]),wz(r[1]),wx(r[2]),wz(r[3])]);
const sfD=(x,z)=>{let d=-1e9;for(const r of SF_R)d=Math.max(d,Math.min(x-r[0],r[2]-x,z-r[1],r[3]-z));return d};
const sfH=d=>SF_BASE+(SF_TOP-SF_BASE)*clamp(d/SF_B,0,1);
const sfTop=(x,z)=>{const d=sfD(x,z);return d>0?sfH(d):0};

function groundHeightAt(x,z){
 if(OFC.has(x,z))return 0;
 const ah=Math.max(audH(x,z),saH(x,z));if(ah>0)return ah;
 const gatePathHeight=GATE_PATHS.heightAt(x,z);if(gatePathHeight!==null)return gatePathHeight;
 if(x>=FP.x0&&x<=FP.x1&&z>=FP.z0&&z<=FP.z1)return FP_TOP;
 for(const r of RAMPS)if(x>=r.x0&&x<=r.x1&&z>=r.z0&&z<=r.z1){
  const t=r.ax==='x'?(x-r.x0)/(r.x1-r.x0):r.dir>0?(z-r.z0)/(r.z1-r.z0):(r.z1-z)/(r.z1-r.z0);
  return FP_TOP-(FP_TOP-RD_TOP)*clamp(t,0,1)}
 {const sf=sfTop(x,z);if(sf>0)return sf}
 if(ADMPAD){const d=Math.min(x-ADMPAD.x0,ADMPAD.x1-x,z-ADMPAD.z0,ADMPAD.z1-z);if(d>0)return RD_TOP+(ADMPAD.top-RD_TOP)*clamp(d/.6,0,1)}
 return roadAt(x,z)}
